using System;using System.IO;using System.Linq;using System.Collections.Generic;using Mewgic;using Mewgic.Core;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;
[InitializeOnLoad]public static class GameplayBoosterTests
{
    static readonly List<string> checks=new List<string>();static readonly Queue<Action> steps=new Queue<Action>();static double next,frameAt;static int frame;static bool recorded;static string initial;
    static GameplayBoosterTests(){EditorApplication.update+=Tick;}
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks.Add(message);}
    static string Key(Puzzle p)=>string.Join("|",p.Export().Select(b=>string.Join(",",b)));
    static string Bag(Puzzle p)=>string.Join("|",p.Export().Select(b=>string.Join(",",b)).OrderBy(s=>s));
    static ProgressLedger Memory(ProgressData data=null)=>new ProgressLedger(data??new ProgressData(),_=>{});
    public static void ModelTests()
    {
        var p=PrototypeApp.LoadLevel();var ledger=Memory();var a=new BoosterActions(p,ledger,p.Count);string start=Key(p);
        Check(!a.Undo()&&ledger.Remaining(BoosterKind.Undo)==3,"Empty Undo does not spend");
        var solution=PuzzleSolver.Solve(p.Export());Check(solution.Status==SearchStatus.Solved&&solution.Moves.Count==3,"Shortest starter solution");
        Check(a.Hint(out var hint)&&hint.Source==solution.Moves[0].Source&&hint.Target==solution.Moves[0].Target&&Key(p)==start&&p.Moves==0&&ledger.Remaining(BoosterKind.Hint)==2,"Hint is verified solution step without model mutation");
        foreach(var move in solution.Moves)Check(p.Pour(move.Source,move.Target)>0,"Verified hint continuation legal");Check(p.Won,"Hint route actually wins");Check(!a.Hint(out _)&&ledger.Remaining(BoosterKind.Hint)==2,"Won puzzle cannot spend hint");
        var stuck=new Puzzle(new[]{new[]{0,1,0,1},new[]{1,0,1,0}});var sl=Memory();var sa=new BoosterActions(stuck,sl,2);Check(PuzzleSolver.Solve(stuck.Export()).Status==SearchStatus.Unsolvable,"Deadlock correctly classified");Check(!sa.Hint(out _)&&sl.Remaining(BoosterKind.Hint)==3,"No random hint in deadlock, no charge");Check(!sa.Shuffle()&&sl.Remaining(BoosterKind.Shuffle)==1,"Unverified shuffle blocked without charge");Check(PuzzleSolver.Solve(PrototypeApp.LoadLevel().Export(),1).Status==SearchStatus.LimitReached,"Search limit is distinct from unsolvable");
        p=PrototypeApp.LoadLevel();ledger=Memory(new ProgressData{undo=0,hint=0,extra=0,shuffle=0});a=new BoosterActions(p,ledger,p.Count);Check(!a.Undo()&&!a.Hint(out _)&&!a.Extra()&&!a.Shuffle()&&Key(p)==start,"Zero balances block every booster");Check(!ledger.TrySpend((BoosterKind)999),"Invalid booster enum blocked");
        p=PrototypeApp.LoadLevel();ledger=Memory();a=new BoosterActions(p,ledger,p.Count);p.Pour(0,2);Check(a.Extra()&&p.Count==5&&p.Bottle(4).Count==0&&p.Moves==1,"One bounded empty bottle, no fake move");Check(!a.Extra()&&p.Count==5,"Extra capped and exhausted");Check(a.Undo()&&p.Count==5&&p.Moves==0&&p.Bottle(0).SequenceEqual(new[]{0,0,1,1}),"Undo preserves purchased empty slot");p.Restart();Check(p.Count==4&&Key(p)==start&&ledger.Remaining(BoosterKind.ExtraBottle)==0,"Restart resets attempt without refilling charges");
        p=PrototypeApp.LoadLevel();ledger=Memory();a=new BoosterActions(p,ledger,p.Count);p.Pour(0,2);string multiset=Bag(p);int moves=p.Moves;Check(a.Shuffle()&&Bag(p)==multiset&&p.Moves==moves,"Shuffle is whole-bottle cyclic permutation");Check(PuzzleSolver.Solve(p.Export()).Status==SearchStatus.Solved,"Shuffle retains verified solution");var expected=PrototypeApp.LoadLevel();expected.RotateBottles();Check(a.Undo()&&Key(p)==Key(expected)&&p.Moves==0,"Undo history follows shuffled bottle positions");Check(!a.Shuffle()&&ledger.Remaining(BoosterKind.Shuffle)==0,"Shuffle cannot overdraw");
        p=PrototypeApp.LoadLevel();p.Pour(0,2);p.AddEmptyBottle(5);p.RotateBottles();expected=PrototypeApp.LoadLevel();expected.AddEmptyBottle(5);expected.RotateBottles();Check(p.Undo()&&Key(p)==Key(expected)&&p.Count==5,"Combined topology history stays exact");
        p=PrototypeApp.LoadLevel();ledger=new ProgressLedger(new ProgressData(),_=>throw new IOException("Simulated disk failure"));a=new BoosterActions(p,ledger,p.Count);Check(!a.Hint(out _)&&!a.Extra()&&!a.Shuffle()&&Key(p)==start&&ledger.Remaining(BoosterKind.Hint)==3,"Save failure cannot spend or mutate puzzle");Check(!ledger.Claim(1,3,true,out var failed)&&!failed&&!ledger.Completed(1),"Failed award save leaves no false award");
        ledger=Memory();Check(!ledger.Claim(1,3,false,out _)&&ledger.Remaining(BoosterKind.Hint)==3,"No reward before victory");Check(ledger.Claim(1,2,true,out bool granted)&&granted&&ledger.Remaining(BoosterKind.Hint)==4,"First completion awards exactly one real hint");Check(ledger.Claim(1,3,true,out granted)&&!granted&&ledger.Remaining(BoosterKind.Hint)==4&&ledger.Snapshot.levels[0].bestStars==3,"Better replay updates stars without duplicate reward");var reloaded=Memory(JsonUtility.FromJson<ProgressData>(JsonUtility.ToJson(ledger.Snapshot)));Check(reloaded.Claim(1,3,true,out granted)&&!granted&&reloaded.Remaining(BoosterKind.Hint)==4,"Reward marker survives serialization and reload");Check(reloaded.Claim(2,3,true,out granted)&&granted&&reloaded.Remaining(BoosterKind.Hint)==5,"Distinct level awards once");
        string testKey="Mewgic.Tests.Part05D."+Guid.NewGuid().ToString("N");try{var disk=GameplayProgress.Open(testKey);Check(disk.TrySpend(BoosterKind.Hint),"Own test save debits");Check(disk.Claim(1,3,true,out granted)&&granted,"Own test save awards");var again=GameplayProgress.Open(testKey);Check(again.Remaining(BoosterKind.Hint)==3&&again.Claim(1,3,true,out granted)&&!granted&&again.Remaining(BoosterKind.Hint)==3,"Actual PlayerPrefs reload prevents duplicate reward");}finally{PlayerPrefs.DeleteKey(testKey);PlayerPrefs.Save();}
        var empty=Memory();Check(!GameplayLevelCatalog.Advance(1,empty)&&GameplayLevelCatalog.SelectedId==1,"Next locked before completed level");foreach(int id in new[]{1,2}){var l=GameplayLevelCatalog.Load(id);var model=new Puzzle(l.Bottles);var path=PuzzleSolver.Solve(model.Export());foreach(var m in path.Moves)Check(model.Pour(m.Source,m.Target)>0,"Catalog path legal "+id);Check(model.Won&&path.Moves.Count==l.OptimalMoves,"Catalog level actually solved "+id);}Check(!GameplayLevelCatalog.CanAdvance(2,ledger),"No fabricated third level");
    }
    static Puzzle Model()=> (Puzzle)typeof(PrototypeApp).GetField("puzzle",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(UnityEngine.Object.FindFirstObjectByType<PrototypeApp>());
    static PrototypeApp App()=>UnityEngine.Object.FindFirstObjectByType<PrototypeApp>();
    static void Click(string name)
    {Canvas.ForceUpdateCanvases();var g=GameObject.Find(name);Check(g!=null,"Button exists "+name);var r=(RectTransform)g.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);Check(hits.Count>0&&hits[0].gameObject==g,"Real touch target "+name);ExecuteEvents.Execute(g,d,ExecuteEvents.pointerClickHandler);}
    static void Count(BoosterKind kind,int expected){string name=new[]{"Undo","Hint","ExtraBottle","Shuffle"}[(int)kind];Check(GameplayProgress.Current.Remaining(kind)==expected,"Ledger balance "+name+"="+expected);Check(GameObject.Find(name).transform.Find("CounterBadge/Charges").GetComponent<TMPro.TMP_Text>().text==expected.ToString(),"Live counter "+name);}
    static void Add(Action a)=>steps.Enqueue(a);static void Tap(string name)=>Add(()=>Click(name));
    static void Pour(int s,int t){Tap("Bottle "+s);Tap("Bottle "+t);Add(()=>Check(!UnityEngine.Object.FindFirstObjectByType<GameplayPresentation>().IsAnimating,"Pour finishes before next action"));}
    public static void Run()
    {
        if(EditorApplication.isPlaying)throw new Exception("Stop Play first");checks.Clear();steps.Clear();frame=0;frameAt=0;recorded=false;GameplayProgress.UseTestProfile();GameplayLevelCatalog.ResetSelection();ModelTests();
        Add(()=>{initial=Key(Model());Capture(1600);Capture(1950);Capture(2000);Capture(2000,true,"-safe");});
        Tap("Bottle 1");Add(()=>{Click("Bottle 3");var before=JsonUtility.ToJson(GameplayProgress.Current.Snapshot);foreach(BoosterKind k in Enum.GetValues(typeof(BoosterKind)))App().UseBooster(k);Check(Model().Moves==1&&Model().Count==4&&before==JsonUtility.ToJson(GameplayProgress.Current.Snapshot),"Busy blocks all boosters and charges");});
        Tap("Undo");Add(()=>{Check(Model().Moves==0,"Undo restores last valid pour");Count(BoosterKind.Undo,2);});
        Tap("Hint");Add(()=>{Count(BoosterKind.Hint,2);Check(GameObject.Find("Status").GetComponent<TMPro.TMP_Text>().text.Contains("1 → 3"),"Hint matches verified route");App().UseBooster(BoosterKind.Hint);Count(BoosterKind.Hint,2);});Tap("Bottle 2");Add(()=>{Check(Model().Moves==0,"Invalid target after hint preserves model");Check(GameObject.Find("Bottle 3").transform.Find("BottleVisual/GlassShell").GetComponent<Outline>().effectColor==Color.clear,"Invalid target clears stale hint halo");Count(BoosterKind.Hint,2);});Tap("Bottle 3");Tap("Undo");
        Tap("Hint");Tap("Bottle 1");Tap("Hint");Tap("Bottle 1");Add(()=>{Count(BoosterKind.Hint,0);var key=Key(Model());App().UseBooster(BoosterKind.Hint);Check(Key(Model())==key&&!GameObject.Find("Hint").GetComponent<Button>().interactable,"Exhausted Hint disabled and guarded");});
        Pour(1,3);Tap("Undo");Pour(1,3);Add(()=>{Count(BoosterKind.Undo,0);App().UseBooster(BoosterKind.Undo);Check(Model().Moves==1,"Exhausted Undo cannot mutate state");});Tap("Restart");
        Add(()=>{Check(Key(Model())==initial,"Restart returns original data");Count(BoosterKind.Undo,0);Count(BoosterKind.Hint,0);});Tap("Shuffle");Add(()=>{Check(PuzzleSolver.Solve(Model().Export()).Status==SearchStatus.Solved,"UI Shuffle remains solvable");Count(BoosterKind.Shuffle,0);var key=Key(Model());App().UseBooster(BoosterKind.Shuffle);Check(Key(Model())==key,"Exhausted Shuffle guarded");});Tap("Restart");
        Tap("ExtraBottle");Add(()=>{Check(Model().Count==5&&GameObject.Find("Bottle 5")!=null,"Extra renders real empty fifth bottle");Count(BoosterKind.ExtraBottle,0);Capture(1600,false,"-extra");Capture(1950,false,"-extra");Capture(2000,true,"-extra-safe");App().UseBooster(BoosterKind.ExtraBottle);Check(Model().Count==5,"No sixth bottle after exhaustion");});Tap("Restart");Add(()=>Check(Model().Count==4&&GameObject.Find("Bottle 5")==null,"Restart removes attempt-only extra without refill"));
        Pour(1,3);Pour(2,1);Pour(2,3);
        Add(()=>{Check(Model().Won&&GameObject.Find("Win panel")!=null,"Winning result shown");Count(BoosterKind.Hint,1);Check(GameplayProgress.Current.Completed(1),"Reward recorded for level one");var before=GameplayProgress.Current.Remaining(BoosterKind.Hint);typeof(PrototypeApp).GetMethod("Refresh",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(App(),null);Check(GameplayProgress.Current.Remaining(BoosterKind.Hint)==before,"Repeated UI refresh cannot award twice");Capture(1600,false,"-win");Capture(1950,false,"-win");Capture(2000,true,"-win-safe");ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART05D_RESULT_GAMEVIEW.png");});
        Tap("Replay");Add(()=>{Check(Model().Moves==0,"Replay resets level");Count(BoosterKind.Hint,1);Count(BoosterKind.Undo,0);});Pour(1,3);Pour(2,1);Pour(2,3);Add(()=>{Count(BoosterKind.Hint,1);Check(GameObject.Find("Reward").GetComponent<TMPro.TMP_Text>().text.Contains("daha önce"),"Replay discloses no second reward");});
        Tap("NextLevel");Add(()=>{Check(GameplayLevelCatalog.SelectedId==2&&Model().Count==5&&UnityEngine.Object.FindFirstObjectByType<GameplayHud>().State.Level==2,"Next loads verified second level");Capture(1600,false,"-level2");Capture(2000,true,"-level2-safe");});
        foreach(var move in PuzzleSolver.Solve(GameplayLevelCatalog.Load(2).Bottles).Moves)Pour(move.Source+1,move.Target+1);
        Add(()=>{Check(Model().Won&&GameplayProgress.Current.Completed(2),"Second verified level wins");Count(BoosterKind.Hint,2);Check(!GameObject.Find("NextLevel").GetComponent<Button>().interactable,"No nonexistent next level");Capture(1600,false,"-level2-win");});Tap("ResultHome");Add(()=>Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="Home","Gameplay next level Home flow"));Tap("Play");Add(()=>Check(GameplayLevelCatalog.SelectedId==2&&Model().Moves==0,"Home Play safely resumes selected verified level"));
        SessionState.SetBool("GameplayBoosterTest",true);EditorSceneManager.OpenScene("Assets/Scenes/Gameplay.unity");EditorApplication.isPlaying=true;next=EditorApplication.timeSinceStartup+1;
    }
    static Rect Bounds(RectTransform t,RectTransform relative){var c=new Vector3[4];t.GetWorldCorners(c);Vector2 min=Vector2.one*float.MaxValue,max=-min;foreach(var p in c){var v=(Vector2)relative.InverseTransformPoint(p);min=Vector2.Min(min,v);max=Vector2.Max(max,v);}return Rect.MinMaxRect(min.x,min.y,max.x,max.y);}
    public static void Capture(int height,bool inset=false,string suffix="")
    {
        var pres=UnityEngine.Object.FindFirstObjectByType<GameplayPresentation>();var canvas=UnityEngine.Object.FindFirstObjectByType<Canvas>();var safe=(RectTransform)GameObject.Find("Safe area").transform;var camera=Camera.main;var min=safe.anchorMin;var max=safe.anchorMax;var mode=canvas.renderMode;var previousCamera=canvas.worldCamera;var dist=canvas.planeDistance;var target=camera.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(900,height,24);Texture2D image=null;
        try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;camera.targetTexture=rt;if(inset){safe.anchorMin=new Vector2(.04f,.05f);safe.anchorMax=new Vector2(.96f,.96f);}Canvas.ForceUpdateCanvases();pres.Layout();Canvas.ForceUpdateCanvases();foreach(var name in new[]{"Undo","Hint","ExtraBottle","Shuffle","Restart","Home"}){var r=(RectTransform)GameObject.Find(name).transform;var b=Bounds(r,safe);Check(safe.rect.Contains(b.min)&&safe.rect.Contains(b.max),"Tool inside safe "+name+height+suffix);Check(r.rect.width*canvas.scaleFactor>=44&&r.rect.height*canvas.scaleFactor>=44,"Touch size "+name+height+suffix);foreach(var bottle in GameObject.Find("Bottle board").GetComponentsInChildren<GameplayBottleView>())Check(!b.Overlaps(Bounds((RectTransform)bottle.transform,safe)),"Tool avoids bottle "+name+height+suffix);}
            if(Model().Won){var panel=(RectTransform)GameObject.Find("Win panel").transform;var bound=Bounds(panel,safe);Check(safe.rect.Contains(bound.min)&&safe.rect.Contains(bound.max),"Result safe "+height+suffix);foreach(var n in new[]{"NextLevel","Replay","ResultHome"}){var r=(RectTransform)GameObject.Find(n).transform;Check(r.rect.width*canvas.scaleFactor>=44&&r.rect.height*canvas.scaleFactor>=44,"Result touch target "+n+height+suffix);}Check(GameObject.Find("Win panel").GetComponentsInChildren<Image>().Count(i=>i.name.StartsWith("GoldParticle"))==24,"Bounded 24 gold particles");}
            camera.Render();RenderTexture.active=rt;image=new Texture2D(900,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,900,height),0,0);image.Apply();File.WriteAllBytes("docs/gameplay-05d-"+height+suffix+".png",image.EncodeToPNG());}
        finally{camera.targetTexture=target;RenderTexture.active=active;canvas.renderMode=mode;canvas.worldCamera=previousCamera;canvas.planeDistance=dist;safe.anchorMin=min;safe.anchorMax=max;if(image!=null)UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);Canvas.ForceUpdateCanvases();pres.Layout();}
    }
    static void Finish(string error){SessionState.SetBool("GameplayBoosterTest",false);File.WriteAllText("docs/PART05D_TEST_RESULTS.json",JsonUtility.ToJson(new Result{success=error==null,error=error,checks=checks.ToArray()},true));EditorApplication.isPlaying=false;GameplayLevelCatalog.ResetSelection();GameplayProgress.RestorePlayerProfile();}
    [Serializable]class Result{public bool success;public string error;public string[] checks;}
    static void Tick(){if(SessionState.GetBool("GameplayBoosterTest",false)&&EditorApplication.isPlaying&&!recorded&&EditorApplication.timeSinceStartup>=frameAt){var result=UnityEngine.Object.FindFirstObjectByType<GameplayEndScreen>();if(result!=null&&result.IsShowing){frameAt=EditorApplication.timeSinceStartup+.08;System.IO.Directory.CreateDirectory("docs/Previews/Part05D");ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/Previews/Part05D/frame"+(frame++).ToString("D3")+".png");if(frame>=12)recorded=true;}}if(!SessionState.GetBool("GameplayBoosterTest",false)||!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;try{next=EditorApplication.timeSinceStartup+1.05;if(steps.Count==0){Finish(null);return;}steps.Dequeue()();}catch(Exception e){Finish(e.ToString());}}
}
